insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0005-0000-4000-8000-00000000002b', 'en', null, 'English Exam Prep: IELTS & TOEFL', 'A practical, encouraging walkthrough of the two big academic English tests - IELTS and TOEFL iBT - covering what they measure, how they are scored, and how to raise your result. You will learn concrete strategies for Listening, Reading, Writing, and Speaking, plus time management and a study plan you can start today. Background on the tests is adapted from Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 89, true, 'humanities', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0005-0000-4000-8000-00000000002b', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: how much do you already know?', 'quiz', '{"questions":[{"prompt":"The IELTS test reports results on a scale called band scores, which run from...","options":["0 to 100","0 to 9","0 to 120","A to F"],"answer":1,"explanation":"IELTS uses band scores from 0 (did not attempt) to 9 (expert user), in half-band steps - see ''What the tests are and how they are scored''."},{"prompt":"A TOEFL iBT total score ranges from...","options":["0 to 9","0 to 100","0 to 120","200 to 800"],"answer":2,"explanation":"TOEFL iBT adds four section scores of 0 to 30 each, for a total from 0 to 120."},{"prompt":"Which four skills do both IELTS and TOEFL assess?","options":["Grammar, spelling, vocabulary, accent","Listening, Reading, Writing, Speaking","Reading, Translation, Dictation, Debate","Only Reading and Writing"],"answer":1,"explanation":"Both tests measure the same four skills: Listening, Reading, Writing, and Speaking."},{"prompt":"On IELTS, Writing Task 2 asks you to produce...","options":["a formal letter","an argumentative or discussion essay","a chart description","a short email"],"answer":1,"explanation":"Task 2 is an essay of at least 250 words; Task 1 differs between the Academic and General versions."},{"prompt":"Skimming a reading passage means...","options":["reading every word slowly","reading quickly to get the main idea and structure","searching for one specific number or name","memorizing the first paragraph"],"answer":1,"explanation":"Skimming is fast reading for the gist and overall organization - different from scanning."},{"prompt":"Scanning is the strategy you use to...","options":["locate a specific piece of information quickly","judge the writer''s tone","summarize the whole text","check your grammar"],"answer":0,"explanation":"Scanning means sweeping the text for a target such as a date, name, or keyword."},{"prompt":"The standard TOEFL iBT is delivered mainly...","options":["on paper by hand","on a computer","by telephone only","in a one-to-one interview"],"answer":1,"explanation":"TOEFL iBT is an internet-based test taken on a computer, including a recorded Speaking section."},{"prompt":"A smart first move before the Listening section begins is to...","options":["close your eyes and relax","read the questions and predict what you will hear","write your essay plan","translate every word into your language"],"answer":1,"explanation":"Reading the questions first lets you predict content and keywords, so you know what to listen for."}]}'::jsonb, null, 10),
  (2, 'What the tests are and how they are scored', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"By the end of this lesson you will be able to explain what IELTS and TOEFL are, say who typically needs each one, and read a score report with confidence. You will know the IELTS band scale from 0 to 9 and the TOEFL iBT scale from 0 to 120, and you will be able to line the two up so that a target on one test translates roughly to the other. Warm-up from the diagnostic: which scale runs from 0 to 9, and which runs from 0 to 120?"},{"heading":"The idea","text":"Both tests measure how well you use English for study and work, and both check the same four skills: Listening, Reading, Writing, and Speaking. The International English Language Testing System, IELTS, is jointly run by three partner organizations and comes in two versions: Academic, for university entry, and General Training, for migration and some work. TOEFL, the Test of English as a Foreign Language, is produced by a United States testing organization and is most often taken in its internet-based form, TOEFL iBT, on a computer. Who needs them? Students applying to English-medium universities, professionals seeking licenses abroad, and people moving to countries such as the United Kingdom, Australia, Canada, or the United States. Background on these tests here is adapted from Wikipedia, the free encyclopedia. Universities and immigration offices set a minimum score, so your job is not a perfect result but a result that clears the bar you need."},{"heading":"Strategies & examples","text":"IELTS gives each skill a band from 0 to 9, then averages the four and rounds to the nearest half-band to produce an overall band. For example, bands of 6.5, 6.0, 7.0, and 6.5 average to 6.5. TOEFL iBT gives each skill a score from 0 to 30 and adds them for a total out of 120. Rough equivalences help you set goals: an IELTS 6.5 is in the region of a TOEFL 79 to 93, and an IELTS 7.0 is near a TOEFL 94 to 101. Treat these as approximate maps, not exact conversions. A practical example: a university asking for ''IELTS 6.5 overall with no band below 6.0'' wants a balanced profile, so one weak skill can block you even when your average looks fine. Check both the overall requirement and any per-skill minimum before you choose a target."},{"heading":"Your turn","text":"1) What is the IELTS band range, and the TOEFL iBT total range? 2) Name the two versions of IELTS. 3) If your four IELTS bands are 7.0, 6.5, 6.5, and 7.0, what is your overall band? 4) Roughly what TOEFL total sits near an IELTS 7.0? 5) A course asks for ''no band below 6.0'' - why does that matter? Answers: 1) IELTS 0 to 9; TOEFL iBT 0 to 120. 2) Academic and General Training. 3) The average is 6.75, which rounds up to 7.0. 4) About 94 to 101. 5) Because a single skill under 6.0 can disqualify you even if your overall average is high enough."},{"heading":"Common mistakes & exit ticket","text":"Mistake: aiming only for an overall score and ignoring a per-skill minimum, then being rejected over one weak section. Mistake: treating equivalence tables as exact - they are approximate bridges between two different scales. Mistake: writing a TOEFL score with a decimal; TOEFL totals are whole numbers. Exit ticket: (a) On which test can you score a 6.5? (b) What is the highest possible TOEFL iBT total? Answers: IELTS, where half-bands exist; 120, the sum of four section scores of 30."}]}'::jsonb, 'IELTS reports half-bands (for example 6.5), while TOEFL iBT reports whole numbers only - do not write a TOEFL score as a decimal.', 13),
  (3, 'The four skills and the format of each test', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"You will be able to describe the shape of each test section by section, and say how IELTS and TOEFL differ in how they present the same four skills. Knowing the format removes surprises on test day, so you can spend your energy answering rather than figuring out what to do. Warm-up: both tests measure the same four skills - can you name them in the order they are usually tested?"},{"heading":"The idea","text":"IELTS runs for about two hours and forty-five minutes. Listening has four recorded sections and forty questions. Reading has three passages and forty questions, with Academic texts drawn from journals and books. Writing has two tasks. Speaking is a face-to-face interview with a human examiner, lasting eleven to fourteen minutes, and may be on a different day. TOEFL iBT runs under two hours in its current form. Reading comes first with academic passages, then Listening with lectures and campus conversations, then Speaking, which you record by speaking into a microphone, and finally Writing. The key structural difference is Speaking: IELTS is a live conversation, while TOEFL is recorded and later scored. TOEFL is also computer-delivered throughout, whereas IELTS offers both paper-based and computer-delivered options."},{"heading":"Strategies & examples","text":"Match your practice to the real format. Because IELTS Listening is heard only once, train yourself to catch answers on a single pass. Because TOEFL lets you take notes during long lectures, practice fast, organized note-taking. For Speaking, rehearse differently for each test: an IELTS candidate practices natural back-and-forth with a partner, while a TOEFL candidate practices speaking clearly to a timer and microphone with no listener reacting. Example: in TOEFL Speaking you often read a short text, hear a talk, then speak for forty-five to sixty seconds - so you must plan in about fifteen seconds. In IELTS Speaking Part 2, you get one minute to prepare a one-to-two-minute talk from a cue card. Knowing these timings lets you build the exact habits each test rewards."},{"heading":"Your turn","text":"1) How many questions are in IELTS Listening? 2) Which section comes first on TOEFL iBT? 3) What is the biggest format difference in the Speaking sections? 4) Is IELTS Listening played once or twice? 5) Which test lets you take notes during lectures? Answers: 1) Forty questions across four sections. 2) Reading. 3) IELTS Speaking is a live interview with an examiner; TOEFL Speaking is recorded by microphone and scored later. 4) Once only, so you cannot wait for a replay. 5) TOEFL iBT, where note-taking during Listening is expected."},{"heading":"Common mistakes & exit ticket","text":"Mistake: assuming the two tests put the sections in the same order - they do not, so practice in each test''s real sequence. Mistake: preparing for Speaking the same way for both, when one is a conversation and one is a recording. Mistake: expecting an IELTS Listening replay; you hear it a single time. Exit ticket: (a) Which test uses a live Speaking interview? (b) Name the four skills every version tests. Answers: IELTS; Listening, Reading, Writing, and Speaking."}]}'::jsonb, 'Say ''take a test'' and ''sit an exam'', not ''make a test'' or ''give an exam'' - these are the natural collocations.', 14),
  (4, 'Listening strategies that actually work', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"You will be able to predict what you are about to hear, lock on to keywords, and take quick notes that turn into correct answers. These three habits - prediction, keyword awareness, and note-taking - are what separate a good listener from someone who simply hopes to catch the right words. Warm-up: before audio starts, what should your eyes be doing?"},{"heading":"The idea","text":"Listening is not passive. Before the recording plays, read the questions and predict the kind of answer each one needs: a number, a name, a place, a date, a reason. This primes your brain so the right words jump out. During the audio, listen for keywords and their synonyms, because tests rarely use the exact word from the question - they paraphrase. If a question mentions ''cost'' you may hear ''price'' or ''fee''. Note-taking is your safety net: jot short cues rather than full sentences, because you cannot write and listen at the same speed. Watch for signpost words such as ''however'', ''finally'', and ''the main reason'', which signal that an answer is coming. In IELTS you hear the recording once, so you must catch it live; in TOEFL you may take notes across a long lecture and use them afterward."},{"heading":"Strategies & examples","text":"Prediction example: a gap-fill reading ''The library closes at ____'' tells you to listen for a time, so you ignore everything else and wait for a clock value. Keyword example: the question says ''the professor recommends'', and in the talk you hear ''I''d suggest you start with...'' - the synonym ''suggest'' marks the answer. Note-taking example: during a lecture on volcanoes, write ''magma -> pressure -> eruption'' instead of full sentences, capturing the chain in three words. Train with distraction too: speakers often correct themselves, saying ''Meet at nine - sorry, make that ten'', and the real answer is the correction. Practice by pausing recordings and predicting the next answer type out loud. Over time, prediction becomes automatic and you stop being surprised."},{"heading":"Your turn","text":"1) Name the three core listening habits. 2) If a question asks about ''cost'', what synonyms might you hear? 3) In ''Meet at nine - sorry, make that ten'', what is the answer? 4) Why take short cues instead of full sentences? 5) How many times is IELTS Listening played? Answers: 1) Prediction, keyword awareness, and note-taking. 2) Price, fee, charge, or rate. 3) Ten, because the speaker corrected the first time. 4) You cannot write full sentences and keep up with the audio; short cues keep you listening. 5) Once only."},{"heading":"Common mistakes & exit ticket","text":"Mistake: waiting for the exact word from the question, when the audio almost always paraphrases it. Mistake: writing so much that you stop listening and miss the next answer. Mistake: keeping the first number you hear when the speaker corrects it. Exit ticket: (a) What should you do in the seconds before audio begins? (b) Why are signpost words like ''however'' useful? Answers: read the questions and predict the answer type; they flag that a key point, often an answer, is coming next."}]}'::jsonb, 'Numbers and spelling count: write ''fourteen'' or ''14'' as the task requires, and spell names exactly as you hear them, letter by letter.', 12),
  (5, 'Reading strategies: skimming, scanning, and question types', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"You will be able to move through a long passage efficiently by skimming for the big picture, scanning for details, and recognizing what each question type is really asking. The reading sections are a race against the clock, so reading every word is a losing plan. Warm-up: which technique finds the main idea fast, and which hunts for one specific fact?"},{"heading":"The idea","text":"Skimming is fast reading for gist: read the title, the first and last sentences of each paragraph, and let the structure form in your mind. Scanning is targeted searching: sweep the page for a specific name, number, or keyword without reading around it. Use skimming first to map the passage, then scan to pin down each answer. Question types each have their own trap. Multiple choice rewards close reading of the options. Matching headings tests whether you grasp each paragraph''s main point. True / False / Not Given asks whether the text supports, contradicts, or simply does not mention a claim - and ''Not Given'' catches people who answer from personal knowledge. Sentence completion usually needs words taken straight from the passage, so copy them exactly and respect any word limit."},{"heading":"Strategies & examples","text":"A reliable routine: skim the whole passage in two to three minutes, then read the questions, then scan back for each answer in order. For matching headings, write a two-word summary of each paragraph before you look at the heading list, so the options cannot mislead you. For True / False / Not Given, example: the text says ''The museum opened in 1908'', and the claim is ''The museum is the oldest in the city.'' That is Not Given, because the passage never compares it to other museums. For sentence completion with a limit of ''no more than two words'', an answer of three words scores zero even if the meaning is right. Keep your answers moving; if one question stalls you, mark it, move on, and return with the time you saved."},{"heading":"Your turn","text":"1) Which technique gets the gist, and which finds a specific fact? 2) In True / False / Not Given, what does ''Not Given'' mean? 3) The text says a museum opened in 1908; the claim says it is the city''s oldest - which answer? 4) If the limit is ''two words'' and you write three, what happens? 5) What is a good first step for matching headings? Answers: 1) Skimming gets the gist; scanning finds the fact. 2) The passage neither confirms nor denies the claim. 3) Not Given, since no comparison is made. 4) You score zero for breaking the word limit. 5) Summarize each paragraph in your own two words before reading the headings."},{"heading":"Common mistakes & exit ticket","text":"Mistake: reading the whole passage word for word and running out of time. Mistake: answering True / False / Not Given from what you personally know instead of what the text states. Mistake: ignoring word limits in completion tasks. Exit ticket: (a) What do you do first, skim or scan? (b) Why can an answer that is correct in meaning still score zero? Answers: skim to map the passage, then scan for details; because it broke the word limit or did not use the passage''s exact words."}]}'::jsonb, 'True / False / Not Given is not the same as True / False - ''Not Given'' means the text neither confirms nor denies the claim, so never guess from outside knowledge.', 13),
  (6, 'Checkpoint 1: formats and input skills', 'quiz', '{"questions":[{"prompt":"Averaging the IELTS bands 6.5, 6.0, 7.0, and 6.5 gives an overall band of...","options":["6.0","6.5","7.0","6.75"],"answer":1,"explanation":"The average is 6.5 exactly, and IELTS reports to the nearest half-band."},{"prompt":"On TOEFL iBT, each of the four skills is scored out of...","options":["9","30","100","120"],"answer":1,"explanation":"Each section scores 0 to 30, and the four add up to a total out of 120."},{"prompt":"Which test uses a live, face-to-face Speaking interview?","options":["TOEFL iBT","IELTS","Both record Speaking","Neither tests Speaking"],"answer":1,"explanation":"IELTS Speaking is a conversation with an examiner; TOEFL Speaking is recorded by microphone."},{"prompt":"Reading quickly to grasp the main idea and structure is called...","options":["scanning","skimming","note-taking","paraphrasing"],"answer":1,"explanation":"Skimming is fast reading for gist; scanning hunts for a specific detail."},{"prompt":"In True / False / Not Given, ''Not Given'' means that the passage...","options":["clearly supports the claim","clearly contradicts the claim","neither confirms nor denies the claim","repeats the claim word for word"],"answer":2,"explanation":"Not Given means the text simply does not address the claim either way."},{"prompt":"Because IELTS Listening is played only once, you should...","options":["wait for the replay to confirm answers","predict answers and catch them on the first pass","read the whole transcript first","write full sentences for every note"],"answer":1,"explanation":"There is no replay, so prediction and quick notes on a single pass are essential."}]}'::jsonb, null, 8),
  (7, 'Writing: IELTS tasks and TOEFL essays', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"You will be able to describe both IELTS writing tasks and both TOEFL essays, structure each one clearly, and name the criteria examiners use to grade them. Writing is where a clear plan pays off most, because a well-organized answer is easier to read and easier to reward. Warm-up: which IELTS task is the essay, and how many words does it need?"},{"heading":"The idea","text":"IELTS Writing has two tasks. In Academic, Task 1 asks you to describe data from a chart, graph, table, or process in at least 150 words; in General Training, Task 1 is a letter. Task 2, on both versions, is an essay of at least 250 words responding to an argument or question. TOEFL iBT writing has two parts as well. The integrated task gives you a short reading and a related lecture, then asks you to summarize how they connect, usually where the lecture challenges the reading. The independent task - in current forms often a ''writing for an academic discussion'' prompt - asks you to state and support your own opinion. The shared truth across all of them is that graders reward a clear position, logical paragraphs, relevant support, and controlled, varied language."},{"heading":"Strategies & examples","text":"Use a reliable skeleton. For an IELTS Task 2 essay: introduction that paraphrases the question and states your position; two body paragraphs, each with one main point, an explanation, and an example; and a short conclusion that restates your view. For IELTS Task 1 data, open with an overview sentence naming the biggest trends, then group details logically rather than listing every number. For a TOEFL integrated task, do not give your opinion; report what the lecture says about each point in the reading, using phrases like ''the lecturer argues'' and ''this casts doubt on the reading''s claim that...''. Example overview for a chart: ''Overall, sales rose steadily across the decade, with the sharpest increase after 2015.'' The criteria graders apply are, broadly: task response, coherence and cohesion, vocabulary, and grammatical range and accuracy - so every improvement should target one of those."},{"heading":"Your turn","text":"1) How many words minimum for IELTS Task 1 and Task 2? 2) What is IELTS General Training Task 1? 3) In a TOEFL integrated task, should you give your own opinion? 4) Name two of the four grading criteria. 5) What belongs in the first sentence of an IELTS Task 1 data answer? Answers: 1) At least 150 words for Task 1; at least 250 for Task 2. 2) A letter. 3) No - you summarize how the lecture relates to the reading. 4) Any two of: task response, coherence and cohesion, vocabulary, grammar. 5) An overview sentence naming the main trend or pattern."},{"heading":"Common mistakes & exit ticket","text":"Mistake: giving your personal opinion in a TOEFL integrated task, which is meant to be a summary. Mistake: listing every number in Task 1 with no overview, so the examiner never sees the big picture. Mistake: writing under the word count and losing marks automatically. Exit ticket: (a) Which IELTS task is the opinion essay? (b) What should the integrated TOEFL response do with the lecture and reading? Answers: Task 2; show how the lecture responds to, usually challenges, the points in the reading."}]}'::jsonb, 'Meet the word counts: IELTS Task 1 needs at least 150 words and Task 2 at least 250 - writing fewer costs you marks.', 14),
  (8, 'Speaking: the parts and how to answer fluently', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"You will be able to describe the parts of each test''s Speaking section and answer with fluency and coherence - speaking at a natural pace, organizing your ideas, and linking them clearly. You will stop freezing on hard questions and instead keep talking in a structured way. Warm-up: on IELTS Part 2, how long do you have to prepare, and how long should you speak?"},{"heading":"The idea","text":"IELTS Speaking has three parts. Part 1 is familiar questions about yourself - home, work, hobbies. Part 2 is the ''long turn'': you get a cue card, one minute to prepare, and then speak for one to two minutes. Part 3 is a discussion of broader, more abstract questions tied to the Part 2 topic. TOEFL Speaking is recorded and has independent and integrated tasks: some ask your opinion on a familiar topic, others ask you to speak based on a short reading and a talk you just heard. In both tests, examiners and raters reward the same qualities: fluency and coherence, a range of vocabulary, grammatical accuracy, and clear pronunciation. The goal is communication, not a perfect accent - being understood and staying organized matters far more than sounding like a native speaker."},{"heading":"Strategies & examples","text":"Structure every answer, even a short one. A handy frame is point, reason, example: state your answer, give a reason, then a concrete example. For ''Do you prefer tea or coffee?'' you might say, ''I prefer coffee, mainly because it helps me focus in the morning - for instance, I always have a cup before I start studying.'' For the IELTS long turn, spend your minute writing three or four cue words covering who, what, when, and why, then speak to them. If you blank, buy time naturally: ''That''s an interesting question - let me think for a second.'' Avoid long silent pauses, which hurt the fluency score. For TOEFL integrated speaking, use your notes and report the source: ''According to the reading... but the professor explains that...''. Practice by recording yourself and checking whether a stranger could follow your points."},{"heading":"Your turn","text":"1) What are the three parts of IELTS Speaking? 2) How long do you prepare and speak in Part 2? 3) What simple frame structures a short answer? 4) Does a native-like accent raise your score? 5) What can you say to buy a moment of thinking time? Answers: 1) Part 1 personal questions, Part 2 the long turn from a cue card, Part 3 abstract discussion. 2) One minute to prepare, one to two minutes to speak. 3) Point, reason, example. 4) No - being clear and understandable matters far more than accent. 5) Something natural like ''That''s an interesting question - let me think for a second.''"},{"heading":"Common mistakes & exit ticket","text":"Mistake: equating fluency with speed and rushing until you stumble. Mistake: freezing in silence instead of using a natural filler to buy time. Mistake: giving one-word answers in Part 1 when examiners want you to extend with a reason. Exit ticket: (a) Which quality matters more, accent or clarity? (b) What three-step frame keeps an answer organized? Answers: clarity and being understood; point, reason, example."}]}'::jsonb, 'Fluency is not speed - a steady pace with brief, natural pauses scores better than rushing and stumbling.', 13),
  (9, 'Key terms for test day', 'vocab', '{"items":[{"term":"band score","translation":"the IELTS result for each skill and overall, from 0 to 9 in half-band steps","example":"She needed an overall band score of 6.5 to enter the program."},{"term":"integrated task","translation":"a TOEFL task that combines two skills, such as reading and listening before you write or speak","example":"In the integrated task you summarize how the lecture responds to the reading."},{"term":"skimming","translation":"reading quickly to get the main idea and overall structure of a text","example":"Start by skimming the passage so you know where each topic sits."},{"term":"scanning","translation":"searching a text rapidly for one specific piece of information","example":"Scanning the paragraph, she found the date in a few seconds."},{"term":"paraphrase","translation":"to say the same meaning using different words","example":"Good essays paraphrase the question rather than copying it word for word."},{"term":"coherence","translation":"the quality of ideas being logically ordered and clearly connected","example":"Linking words improve the coherence of a spoken answer."},{"term":"cue card","translation":"the card in IELTS Speaking Part 2 that gives you a topic and points to cover","example":"He used his minute to note four ideas from the cue card."},{"term":"proficiency","translation":"a high level of skill in using a language","example":"Both tests are measures of English proficiency for study and work."}]}'::jsonb, null, 9),
  (10, 'Time management, test-day tips, and a study plan', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"You will be able to manage your time during each section, walk into the test calm and prepared, and follow a realistic study plan that steadily raises your score. Knowledge alone does not pass these tests - pacing and preparation do. Warm-up: if one question is costing you too much time, what should you do?"},{"heading":"The idea","text":"Time management means spending your minutes in proportion to the marks on offer and never letting one hard item sink a whole section. Set a rough budget: in IELTS Reading, roughly twenty minutes per passage; in Writing, about twenty minutes on Task 1 and forty on Task 2, because Task 2 is worth more. If a question stalls you, mark it, move on, and come back with leftover time. Test-day readiness is partly logistics: sleep well, eat, arrive early, and bring the exact identification the test requires. A study plan turns a vague wish into weekly action. Decide your target score, take a timed practice test to find your weakest skill, and give that skill the most attention. Steady, spaced practice beats one exhausting session, and regular full-length rehearsals under real timing build the stamina these long tests demand."},{"heading":"Strategies & examples","text":"A sample eight-week plan: Week 1, take a full timed practice test and record each section score to find your baseline. Weeks 2 to 5, rotate focused practice - two days on your weakest skill, one day each on the others - and learn ten useful words a day. Weeks 6 to 7, do two full timed mock tests and review every mistake, asking why the right answer is right. Week 8, taper: light review, rehearse your Speaking frames, prepare your documents, and rest the day before. Example of time discipline: in Writing, if forty minutes are gone and Task 2 is only half done, stop polishing and write your conclusion, because an unfinished essay is penalized. Example of review: do not just mark an answer wrong - write one sentence on the reason, so the same trap does not catch you twice. Small, repeated corrections are how scores climb."},{"heading":"Your turn","text":"1) Roughly how long per passage in IELTS Reading? 2) Why give IELTS Task 2 more time than Task 1? 3) What is the first step in a study plan? 4) If one question stalls you, what do you do? 5) Why review mistakes with a written reason? Answers: 1) About twenty minutes each, across three passages. 2) Task 2 carries more marks toward the Writing score. 3) Take a timed practice test to find your baseline and weakest skill. 4) Mark it, move on, and return with any leftover time. 5) Writing the reason stops you from repeating the same mistake."},{"heading":"Common mistakes & exit ticket","text":"Mistake: spending too long on one tough question and running out of time for easy marks later. Mistake: practicing without a clock, so test-day timing feels alien. Mistake: cramming the night before instead of resting. Exit ticket: (a) Which IELTS writing task deserves more of your time, and why? (b) What is the smartest way to find out where to focus your study? Answers: Task 2, because it is worth more marks; take a full timed practice test to reveal your weakest skill. You are ready - make a plan, practice under real timing, and keep going."}]}'::jsonb, 'Plan backward from your test date: fix the goal first, then schedule the weeks - ''I will test in eight weeks'' shapes every study session.', 13)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0005-0000-4000-8000-00000000002b' and l.position = v.pos
);
